import {Sheet,SheetContent,SheetHeader,SheetTitle,SheetDescription} from './ui/sheet';
import {OpportunityImport,downloadOpportunities} from './opportunity-import';
import {apiFetch,session} from '../main';
import {opportunityDate,opportunityStatusLabels} from '@/lib/opportunity-types';
import {canQuoteOpportunity,canRejectOpportunity,isOpportunityQuoted,nextOpportunityDayChange,opportunityDeadline,opportunityLocalDate,opportunityTimezone,safeOpportunityLink} from '@/lib/opportunity-display';
