const statusIcons={pending:Clock,approved:CheckCircle2,rejected:XCircle,expired:CalendarDays};
const defaultRegions=[{code:'NSW',origin:'63-79 Parramatta Rd Silverwater, NSW 2128',timezone:'Australia/Sydney'},{code:'VIC',origin:'CBD, Melbourne',timezone:'Australia/Melbourne'}];
type Draft={id?:string;revision?:number;project:string;builders:string[];region:string;location:string;due:string;workingScope:string;remarks:string;link:string;value:number|null;distanceKm:number|null;distanceOrigin:string;category:string;budget:string;addedDate:string};
type Management={kind:'assign'|'access';teams:number[];users:number[]};
type Decision=OpportunityStatus|'delete';
type QuoteDraft={id:string;revision:number;project:string;value:string;note:string;quoteNo:string;submittedDate:string;submittedByTeamId:string;builders:string[];availableBuilders:string[]};
type OpportunitiesProps={requestedId:string|null;onRequestHandled:()=>void;onOpenChaseUp:(submissionId:string)=>void;onSubmissionsChanged:()=>Promise<void>|void};
const blankDraft=():Draft=>({project:'',builders:[],region:'NSW',location:'',due:'',workingScope:'',remarks:'',link:'',value:null,distanceKm:null,distanceOrigin:defaultRegions[0].origin,category:'',budget:'',addedDate:''});
function draftOf(item:Opportunity):Draft {return {id:item.id,revision:item.revision,project:item.project,builders:[...item.builders],region:item.region,location:item.location,due:item.due,workingScope:item.workingScope||'',remarks:item.remarks||'',link:item.link||'',value:item.value,distanceKm:item.distanceKm,distanceOrigin:item.distanceOrigin,category:item.category||'',budget:item.budget||'',addedDate:item.addedDate||''}}
function StatusBadge({status}:{status:OpportunityStatus}){const Icon=statusIcons[status]||Clock;return <span className={'op-status op-status-'+status}><Icon size={13}/>{opportunityStatusLabels[status]||status}</span>}
function toggleId(list:number[],id:number){return list.includes(id)?list.filter(value=>value!==id):[...list,id]}
const moneyFormatter=new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD',maximumFractionDigits:0});
const quoteMoneyFormatter=new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD',minimumFractionDigits:2,maximumFractionDigits:2});
function Money({value,precise=false}:{value:number|null;precise?:boolean}){return <>{value==null?'Value not recorded':(precise?quoteMoneyFormatter:moneyFormatter).format(value)}</>}
function DeadlineBadge({item,regions,now}:{item:Opportunity;regions:OpportunityRegion[];now:number}){
  const deadline=opportunityDeadline(item,regions,now);
  return <span className={'op-deadline op-deadline-'+deadline.tone} title={deadline.days===null?undefined:'Calendar days · deadline at the end of the day in '+deadline.timezone}><CalendarDays size={18} aria-hidden="true"/>{deadline.label}</span>;
}
function OpportunityLink({value,project,compact=false}:{value?:string;project:string;compact?:boolean}){
  const href=safeOpportunityLink(value);if(!href)return null;
  return <a className={'op-project-external-link'+(compact?' op-card-external-link':'')} href={href} target="_blank" rel="noopener noreferrer" aria-label={'Open project link for '+project+' in a new tab'} title={href}><Link2 size={15} aria-hidden="true"/><span>{compact?<>Open link <span className="op-link-host">· {new URL(href).hostname}</span></>:href}</span><ArrowUpRight size={14} aria-hidden="true"/></a>;
}
function useDeadlineClock(regions:OpportunityRegion[]){
  const [now,setNow]=useState(()=>Date.now());
  const timezones=[...new Set(regions.map(region=>opportunityTimezone(region.code,regions)))].sort().join('|');
  useEffect(()=>{
    let timer:number;
    const update=()=>{
      window.clearTimeout(timer);const instant=Date.now();setNow(instant);
      timer=window.setTimeout(update,nextOpportunityDayChange(timezones.split('|').filter(Boolean),instant)-instant+25);
    };
    const onVisible=()=>{if(document.visibilityState==='visible')update()};
    update();window.addEventListener('focus',update);document.addEventListener('visibilitychange',onVisible);
    return()=>{window.clearTimeout(timer);window.removeEventListener('focus',update);document.removeEventListener('visibilitychange',onVisible)};
  },[timezones]);
  return now;
}
function ChoiceList({title,items,selected,onChange,empty}:{title:string;items:{id:number;name:string;hint?:string}[];selected:number[];onChange:(ids:number[])=>void;empty:string}){
  const [search,setSearch]=useState('');
  const shown=items.filter(item=>[item.name,item.hint].join(' ').toLowerCase().includes(search.toLowerCase()));
  return <fieldset className="op-choice-group"><legend>{title}<span>{selected.length} selected</span></legend>{items.length>8&&<input type="search" aria-label={'Find '+title.toLowerCase()} placeholder={'Find '+title.toLowerCase()+'…'} value={search} onChange={e=>setSearch(e.target.value)}/>}<div className="op-choice-list">{shown.map(item=><label key={item.id}><input type="checkbox" checked={selected.includes(item.id)} onChange={()=>onChange(toggleId(selected,item.id))}/><span><b>{item.name}</b>{item.hint&&<small>{item.hint}</small>}</span></label>)}{!items.length&&<p className="op-help">{empty}</p>}{items.length>0&&!shown.length&&<p className="op-help">No matching people.</p>}</div></fieldset>;
}
function ActivityDetails({details}:{details:OpportunityActivity['details']}) {
  if(!details||!Object.keys(details).length)return null;
  const readable=(value:unknown):string=>value==null?'—':typeof value==='string'?value:typeof value==='object'?JSON.stringify(value):String(value);
  return <details className="op-audit-details"><summary>View recorded details</summary><dl>{Object.entries(details).map(([key,value])=><div key={key}><dt>{key.replace(/([a-z])([A-Z])/g,'$1 $2').replaceAll('_',' ')}</dt><dd>{readable(value)}</dd></div>)}</dl></details>;
}
function SourceInfo({source}:{source:Record<string,unknown>}) {
  const warnings=Array.isArray(source.warnings)?source.warnings.filter((item):item is string=>typeof item==='string'):[];
  const cells=Array.isArray(source.cells)?source.cells as {column:string;header:string;value:unknown;formula?:string}[]:[];
  const display=(value:unknown):string=>value==null?'—':typeof value==='boolean'?(value?'Yes':'No'):typeof value==='object'?JSON.stringify(value):String(value);
  return <>{warnings.length>0&&<section className="op-detail-section op-source-warnings"><h3>Source notes</h3>{warnings.map((warning,i)=><p key={i}>{warning}</p>)}</section>}<details className="op-source-details"><summary>Original workbook details</summary><dl>{Object.entries(source).filter(([key])=>!key.startsWith('_')&&!['cells','warnings'].includes(key)).map(([key,value])=><div key={key}><dt>{key}</dt><dd>{display(value)}</dd></div>)}</dl>{cells.length>0&&<div className="op-source-table-wrap"><table className="op-source-table"><thead><tr><th>Workbook column</th><th>Original value</th></tr></thead><tbody>{cells.map((cell,i)=><tr key={i}><th scope="row">{cell.header||cell.column}<small>Column {cell.column}</small></th><td>{display(cell.value)}{cell.formula&&<small>Formula: {cell.formula}</small>}</td></tr>)}</tbody></table></div>}</details></>;
}

export default function Opportunities({requestedId,onRequestHandled,onOpenChaseUp,onSubmissionsChanged}:OpportunitiesProps) {
  const [result,setResult]=useState<OpportunityList|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState('');
  const [query,setQuery]=useState(''),[search,setSearch]=useState(''),[status,setStatus]=useState<OpportunityStatus|'all'>('pending');
  const [region,setRegion]=useState(''),[team,setTeam]=useState(''),[person,setPerson]=useState(''),[sort,setSort]=useState('due'),[page,setPage]=useState(1);
  const [teamView,setTeamView]=useState(false),[reload,setReload]=useState(0),[selectedId,setSelectedId]=useState<string|null>(null);
  const [detail,setDetail]=useState<OpportunityDetail|null>(null),[detailLoading,setDetailLoading]=useState(false),[detailError,setDetailError]=useState('');
  const [detailTab,setDetailTab]=useState('overview'),[form,setForm]=useState<Draft|null>(null),[builderDraft,setBuilderDraft]=useState('');
  const [management,setManagement]=useState<Management|null>(null),[decision,setDecision]=useState<Decision|null>(null),[reason,setReason]=useState('');
  const [quote,setQuote]=useState<QuoteDraft|null>(null);
  const [busy,setBusy]=useState(false),[actionError,setActionError]=useState(''),[activityLoading,setActivityLoading]=useState(false),[activityError,setActivityError]=useState('');
  const activityPending=useRef(false);
  const listRequest=useRef<AbortController|null>(null),detailRequest=useRef<AbortController|null>(null),writePending=useRef(false);
  const selected=detail?.opportunity;
  const regions=result?.regions?.length?result.regions:defaultRegions,teams=result?.teams||[],users=result?.users||[];
  const deadlineNow=useDeadlineClock(regions);
  const canQuote=(item:Opportunity)=>canQuoteOpportunity(item,regions,deadlineNow);
  const canReject=(item:Opportunity)=>canRejectOpportunity(item,regions,deadlineNow);
  const rejectingQuote=decision==='rejected'&&selected&&canQuote(selected);
  const teamNames=useMemo(()=>new Map(teams.map(t=>[t.id,t.name])),[teams]);
  const userNames=useMemo(()=>new Map(users.map(u=>[u.id,u.name])),[users]);
  useEffect(()=>{const timer=setTimeout(()=>{setSearch(query);setPage(1)},250);return()=>clearTimeout(timer)},[query]);
  const loadList=useCallback(async()=>{
    listRequest.current?.abort();const controller=new AbortController();listRequest.current=controller;setLoading(true);setError('');
    const params=new URLSearchParams({q:search,status,page:String(page),pageSize:'20',sort});
    if(region)params.set('region',region);if(team)params.set('teamId',team);if(person)params.set('userId',person);
    try {
      const response=await apiFetch('opportunities?'+params,{signal:controller.signal});
      const data=await response.json();if(!response.ok)throw Error(data.error||'Unable to load opportunities.');
      if(!controller.signal.aborted){setResult(data);const last=Math.max(1,Math.ceil(data.total/20));if(page>last)setPage(last)}
    }catch(e){if(!controller.signal.aborted)setError((e as Error).message)}finally{if(!controller.signal.aborted)setLoading(false)}
  },[search,status,page,sort,region,team,person]);
  useEffect(()=>{void loadList();return()=>listRequest.current?.abort()},[loadList,reload]);
  useEffect(()=>{const refresh=()=>{if(document.visibilityState==='visible'&&!writePending.current)setReload(n=>n+1)};const timer=setInterval(refresh,60000);window.addEventListener('focus',refresh);return()=>{clearInterval(timer);window.removeEventListener('focus',refresh)}},[]);
  const loadDetail=useCallback(async(id:string)=>{
    detailRequest.current?.abort();const controller=new AbortController();detailRequest.current=controller;setDetailLoading(true);setDetailError('');
    try {const response=await apiFetch('opportunities/detail?id='+encodeURIComponent(id),{signal:controller.signal});const data=await response.json();if(!response.ok)throw Error(data.error||'Unable to load this opportunity.');if(!controller.signal.aborted)setDetail(data)}catch(e){if(!controller.signal.aborted)setDetailError((e as Error).message)}finally{if(!controller.signal.aborted)setDetailLoading(false)}
  },[]);
  useEffect(()=>{if(selectedId)void loadDetail(selectedId);else{detailRequest.current?.abort();setDetail(null)}return()=>detailRequest.current?.abort()},[selectedId,loadDetail]);
  useEffect(()=>{if(requestedId){setSelectedId(requestedId);setDetailTab('overview');onRequestHandled()}},[requestedId,onRequestHandled]);
  function openItem(id:string){setSelectedId(id);setDetailTab('overview');setDetail(null);setActionError('');setActivityError('')}
  // Card actions need the record as context, without opening a second modal
  // alongside their action dialog. An already-open detail sheet stays open.
  function selectActionItem(item:Opportunity){setDetail(previous=>previous?.opportunity.id===item.id?{...previous,opportunity:item}:{opportunity:item,activity:[]});setDetailTab('overview');setActionError('');setActivityError('')}
  function openQuote(item:Opportunity){
    selectActionItem(item);
    const actorTeam=users.find(user=>user.id===session.user.id)?.teamId;
    const assigned=(item.assignedTeamIds||[]).filter(id=>teams.some(team=>team.id===id));
    const defaultTeam=assigned.length===1?assigned[0]:actorTeam;
    setQuote({id:item.id,revision:item.revision,project:item.project,value:'',note:'',quoteNo:'',submittedDate:opportunityLocalDate(item.region,regions),submittedByTeamId:defaultTeam&&teams.some(team=>team.id===defaultTeam)?String(defaultTeam):'',builders:[...item.builders],availableBuilders:[...item.builders]});
  }
  function markNotQuoted(item:Opportunity){selectActionItem(item);setDecision('rejected');setReason('')}
  function rejectOpportunity(item:Opportunity){selectActionItem(item);setDecision('rejected');setReason('')}
  function edit(item?:Opportunity){setForm(item?draftOf(item):blankDraft());setBuilderDraft('');setActionError('')}
  function clearFilters(){setQuery('');setSearch('');setStatus('all');setRegion('');setTeam('');setPerson('');setSort('due');setPage(1)}
  async function changed(){setReload(n=>n+1);window.dispatchEvent(new Event('tenders:notifications-changed'))}
  async function mutate(path:string,body:unknown,method='POST') {
    if(writePending.current)return null;writePending.current=true;setBusy(true);setActionError('');
    try {const response=await apiFetch('opportunities'+path,{method,body:JSON.stringify(body)});const data=await response.json();if(!response.ok){if(response.status===409){if(selectedId)void loadDetail(selectedId);void changed()}throw Error(data.error||'This change could not be saved.')}if(data.opportunity)setDetail(data);await changed();return data}
    catch(e){setActionError((e as Error).message);return null}finally{writePending.current=false;setBusy(false)}
  }
  function addBuilder(){if(!form||!builderDraft.trim())return;const key=(name:string)=>name.normalize('NFKC').toLocaleLowerCase().replace(/[^\p{L}\p{N}_]/gu,'');const name=(result?.builders||[]).find(value=>key(value)===key(builderDraft))||builderDraft.trim();if(form.builders.some(value=>key(value)===key(name))){setActionError('This builder is already added.');return}setForm({...form,builders:[...form.builders,name]});setBuilderDraft('');setActionError('')}
  async function saveForm(e:React.FormEvent){e.preventDefault();if(!form)return;const payload={...form,builders:[...form.builders,...(builderDraft.trim()?[builderDraft.trim()]:[])]};if(!payload.project.trim()){setActionError('Enter a project name.');return}const data=await mutate('/save',payload);if(data){setForm(null);setSelectedId(data.opportunity.id);setDetailTab('overview');toast.success(form.id?'Opportunity updated':'Opportunity added for approval')}}
  async function saveManagement(e:React.FormEvent){e.preventDefault();if(!management||!selected)return;const beforeStatus=selected.status;const body={id:selected.id,revision:selected.revision,...(management.kind==='assign'?{assignedTeamIds:management.teams,assignedUserIds:management.users}:{editorTeamIds:management.teams,editorUserIds:management.users})};const data=await mutate('/'+management.kind,body);if(data){toast.success(management.kind==='assign'?(beforeStatus!=='approved'&&data.opportunity.status==='approved'?'Team assigned and opportunity approved':'Assignments updated'):'Editing access updated');setManagement(null)}}
  async function saveQuote(e:React.FormEvent){
    e.preventDefault();if(!quote)return;
    const value=Number(quote.value);
    if(!quote.value.trim()||!Number.isFinite(value)||value<0){setActionError('Enter the electrical services submission value, zero or greater.');return}
    if(!quote.builders.length){setActionError('Choose at least one builder who received the quote.');return}
    const data=await mutate('/quote',{id:quote.id,revision:quote.revision,value,note:quote.note,quoteNo:quote.quoteNo,submittedDate:quote.submittedDate,submittedByTeamId:quote.submittedByTeamId?Number(quote.submittedByTeamId):null,builders:quote.builders});
    if(!data)return;
    setQuote(null);setSelectedId(data.opportunity.id);setDetailTab('overview');
    try{await onSubmissionsChanged()}catch{toast.info('Quote saved. Refresh Project Chase-up to load the new submission.')}
    const submissionId=data.submissionIds?.[0]||data.opportunity.submissionIds?.[0];
    toast.success(data.alreadyQuoted?'This quote is already in Project Chase-up':'Quote saved to Projects and Project Chase-up',submissionId?{action:{label:'Open chase-up',onClick:()=>onOpenChaseUp(submissionId)}}:undefined);
    if(submissionId)onOpenChaseUp(submissionId);
  }
  async function saveDecision(e:React.FormEvent){e.preventDefault();if(!selected||!decision)return;const result=await mutate(decision==='delete'?'':'/decision',{id:selected.id,revision:selected.revision,decision,reason},decision==='delete'?'DELETE':'POST');if(result){if(decision==='delete'){setSelectedId(null);setDetail(null);toast.success('Opportunity deleted; activity retained')}else toast.success(decision==='pending'?'Opportunity sent for approval':decision==='approved'?'Opportunity approved':'Opportunity rejected');setDecision(null);setReason('')}}
  async function loadOlderActivity(){
    if(!selected||!detail?.nextActivityCursor||activityPending.current)return;
    activityPending.current=true;setActivityLoading(true);setActivityError('');const id=selected.id;
    try{const response=await apiFetch('opportunities/activity?'+new URLSearchParams({id,before:String(detail.nextActivityCursor),limit:'100'}));const result=await response.json();if(!response.ok)throw Error(result.error||'Unable to load older activity.');setDetail(previous=>previous?.opportunity.id===id?{...previous,activity:[...previous.activity,...result.activity.filter((event:OpportunityActivity)=>!previous.activity.some(item=>item.id===event.id))],hasMoreActivity:result.hasMoreActivity,nextActivityCursor:result.nextActivityCursor,activityTotal:result.total??previous.activityTotal}:previous)}catch(e){setActivityError((e as Error).message)}finally{activityPending.current=false;setActivityLoading(false)}
  }
  function assignedNames(item:Opportunity){return [...(item.assignedTeamIds||[]).map(id=>teamNames.get(id)||'Former team'),...(item.assignedUserIds||[]).map(id=>userNames.get(id)||'Former user')]}
  const filterCount=[status!=='all',region,team,person,search].filter(Boolean).length;
  const currentPage=result?.page||page,totalPages=Math.max(1,Math.ceil((result?.total||0)/20));
  const statusList:OpportunityStatus[]=['pending','approved','rejected','expired'];
  const activeTeamName=team==='unassigned'?'No team assigned':teams.find(t=>String(t.id)===team)?.name;
  const currentTitle=activeTeamName?activeTeamName+' opportunities':person===String(session.user.id)?'Assigned to me':status==='all'?'All opportunities':opportunityStatusLabels[status];
  return <section className="op-workspace" aria-label="Opportunities">
    <div className="op-heading"><div><p className="op-eyebrow">UPCOMING PROJECTS</p><h2>From opportunity to approval</h2><p>Track potential work, agree the scope and bring the right team in.</p></div><div className="op-heading-actions"><OpportunityImport regions={regions} onImported={changed}/><button className="secondary-btn" onClick={async()=>{try{const params=new URLSearchParams({status,region,teamId:team,userId:person,q:search});await downloadOpportunities('?'+params)}catch(e){toast.error((e as Error).message)}}}><Download size={16}/>Export</button><button className="primary-btn" onClick={()=>edit()}><Plus size={17}/>New opportunity</button></div></div>
    <div className="op-stats" aria-label="Opportunity status filters">{statusList.map(value=>{const Icon=statusIcons[value];return <button key={value} className={'op-stat op-stat-'+value} aria-pressed={status===value} onClick={()=>{setStatus(status===value?'all':value);setPage(1)}}><span><Icon size={17}/>{opportunityStatusLabels[value]}</span><strong>{result?.counts[value]??'—'}</strong><small>{value==='pending'?'Ready for a decision':value==='approved'?'Accepted to progress':value==='rejected'?'Decision recorded':'Deadline has passed'}</small></button>})}</div>
    <div className="op-register panel"><div className="op-register-heading"><div><h2>{currentTitle}</h2><p>{result?.total??0} opportunit{result?.total===1?'y':'ies'}{loading&&result?' · Updating…':''}</p></div><div className="op-view-toggle" role="group" aria-label="Opportunity list view"><button aria-pressed={!teamView} onClick={()=>setTeamView(false)}><ClipboardList size={15}/>All projects</button><button aria-pressed={teamView} onClick={()=>setTeamView(true)}><Users size={15}/>By team</button></div></div>
      {teamView&&<div className="op-team-directory"><button className={!team?'is-active':''} onClick={()=>{setTeam('');setPage(1)}}><Users size={18}/><span>All teams</span></button>{(result?.teamCounts||[]).map(entry=><button key={entry.id} className={team===String(entry.id)?'is-active':''} onClick={()=>{setTeam(String(entry.id));setPage(1)}}><span className="op-team-initial">{entry.name.slice(0,1)}</span><span>{entry.name}</span><strong title="Total opportunities assigned to this team in the full register">{entry.count}</strong></button>)}{!teams.length&&<p className="op-help">Create teams in Manage Users to assign upcoming work.</p>}</div>}
      <div className="op-toolbar"><label className="op-compact-field"><span>Status</span><select aria-label="Opportunity status" value={status} onChange={e=>{setStatus(e.target.value as typeof status);setPage(1)}}><option value="all">All statuses</option>{statusList.map(value=><option key={value} value={value}>{opportunityStatusLabels[value]}</option>)}</select></label><label className="op-compact-field"><span>Region</span><select aria-label="Opportunity region" value={region} onChange={e=>{setRegion(e.target.value);setPage(1)}}><option value="">All regions</option>{regions.map(r=><option key={r.code} value={r.code}>{r.code}</option>)}</select></label><label className="op-compact-field"><span>Team</span><select aria-label="Assigned opportunity team" value={team} onChange={e=>{setTeam(e.target.value);setPage(1)}}><option value="">All teams</option><option value="unassigned">No team assigned</option>{teams.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label><label className="op-compact-field"><span>Person</span><select aria-label="Assigned opportunity person" value={person} onChange={e=>{setPerson(e.target.value);setPage(1)}}><option value="">Everyone</option><option value={session.user.id}>Assigned to me</option>{users.filter(u=>u.id!==session.user.id).map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></label><div className="op-search" role="search"><Search size={17}/><input aria-label="Search opportunities" type="search" maxLength={300} value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search projects, builders or scope…"/>{query&&<button className="icon-btn" aria-label="Clear opportunity search" onClick={()=>setQuery('')}><X size={15}/></button>}</div></div>
      <div className="op-list-options"><span>{regions.find(r=>r.code===region)?.origin?`Distance from ${regions.find(r=>r.code===region)!.origin}`:'Distances use each region’s office or nominated origin.'}</span>{filterCount>0&&<button className="text-btn" onClick={clearFilters}>Clear filters ({filterCount})</button>}<label>Sort <select aria-label="Sort opportunities" value={sort} onChange={e=>{setSort(e.target.value);setPage(1)}}><option value="due">Deadline</option><option value="updated">Recently updated</option><option value="name">Project name</option></select></label></div>
      {error&&<div className="error-banner" role="alert">{error}<button onClick={()=>loadList()}><RefreshCw size={15}/>Retry</button></div>}
      {loading&&!result?<div className="op-loading" role="status"><RefreshCw className="op-spin" size={23}/>Loading opportunities…</div>:<div className="op-cards" aria-busy={loading}>{result?.items.map(item=>{const assigned=assignedNames(item);return <article key={item.id} className="op-card">
        <div className="op-card-top"><StatusBadge status={item.status}/><span className="op-region">{item.region}</span></div>
        <button className="op-project-link" onClick={()=>openItem(item.id)}>{item.project}<ArrowUpRight size={17}/></button><p className="op-builders"><Building2 size={14}/>{item.builders.length?item.builders.join(' · '):'Builder to be confirmed'}</p>{item.workingScope&&<p className="op-card-scope">{item.workingScope}</p>}
        <div className="op-card-deadline"><DeadlineBadge item={item} regions={regions} now={deadlineNow}/>{item.due&&<time dateTime={item.due}>{opportunityDate(item.due)}</time>}</div>
        <div className="op-card-facts"><span><MapPin size={14}/>{item.location||'Location to be confirmed'}</span></div><OpportunityLink value={item.link} project={item.project} compact/>
        <div className="op-card-meta"><span>{item.budget?`Budget: ${item.budget}`:<Money value={item.value}/>}</span>{item.distanceKm!=null&&<span title={'Distance from '+item.distanceOrigin}>{item.distanceKm} km</span>}</div>
        <div className="op-card-footer"><span className="op-assignees"><Users size={15}/>{assigned.length?assigned.join(' · '):'Not assigned'}</span><button className="secondary-btn" onClick={()=>openItem(item.id)}>View details</button></div>
        {item.status==='approved'&&isOpportunityQuoted(item)&&<div className="op-card-quoted"><span><FileCheck2 size={17}/><b>Quoted</b>{item.quotedValue!=null&&<Money value={item.quotedValue} precise/>}</span>{item.submissionIds?.[0]&&<button className="secondary-btn" onClick={()=>onOpenChaseUp(item.submissionIds![0])}>Open Project Chase-up<ArrowUpRight size={15}/></button>}</div>}
        {canQuote(item)&&<div className="op-quote-actions" aria-label={'Quote outcome for '+item.project}><button className="primary-btn" disabled={busy} onClick={()=>openQuote(item)}><FileCheck2 size={16}/>Quoted</button><button className="secondary-btn danger-text" disabled={busy} onClick={()=>markNotQuoted(item)}><XCircle size={16}/>Not quoted</button></div>}
      </article>})}{!result?.items.length&&!error&&<div className="op-empty"><ClipboardList size={33}/><h3>{filterCount?'No opportunities match these filters':'No opportunities yet'}</h3><p>{filterCount?'Try another team, region or search.':'Add a potential project or import your opportunity workbook.'}</p><button className="secondary-btn" onClick={filterCount?clearFilters:()=>edit()}>{filterCount?'Clear filters':'Add opportunity'}</button></div>}</div>}
      {(result?.total||0)>0&&<div className="pagination op-pagination"><span>{(currentPage-1)*20+1}–{Math.min(currentPage*20,result!.total)} of {result!.total}</span><div><button className="icon-btn" aria-label="Previous opportunities page" disabled={currentPage<=1||loading} onClick={()=>setPage(currentPage-1)}><ChevronLeft size={19}/></button><span>Page {currentPage} of {totalPages}</span><button className="icon-btn" aria-label="Next opportunities page" disabled={currentPage>=totalPages||loading} onClick={()=>setPage(currentPage+1)}><ChevronRight size={19}/></button></div></div>}
    </div>

    <Sheet open={!!selectedId} onOpenChange={open=>{if(!open)setSelectedId(null)}}><SheetContent className="op-detail-sheet"><SheetHeader><div className="op-eyebrow">OPPORTUNITY</div><SheetTitle>{selected?.project||'Opportunity details'}</SheetTitle><SheetDescription>{selected?`${selected.region} · Created by ${selected.createdByName||'Workbook import'}`:'Loading project information'}</SheetDescription></SheetHeader>
      {detailLoading&&!selected&&<div className="op-loading" role="status"><RefreshCw className="op-spin" size={20}/>Loading details…</div>}{detailError&&<div className="error-banner" role="alert">{detailError}<button onClick={()=>selectedId&&loadDetail(selectedId)}>Retry</button></div>}
      {selected&&<div className="op-detail-body"><div className="op-detail-status">{selected.deletedAt?<span className="op-status op-status-expired">Deleted · history retained</span>:<StatusBadge status={selected.status}/>}<strong>{selected.budget?`Budget: ${selected.budget}`:<Money value={selected.value}/>}</strong></div><div className="op-detail-actions">
        {!selected.deletedAt&&selected.permissions.edit&&<button className="secondary-btn" onClick={()=>edit(selected)}><Pencil size={15}/>Edit</button>}
        {!selected.deletedAt&&selected.permissions.manage&&<><button className="secondary-btn" onClick={()=>{setActionError('');setManagement({kind:'assign',teams:selected.assignedTeamIds||[],users:selected.assignedUserIds||[]})}}><Users size={15}/>Assign</button><button className="secondary-btn" onClick={()=>{setActionError('');setManagement({kind:'access',teams:selected.editorTeamIds||[],users:selected.editorUserIds||[]})}}><ShieldCheck size={15}/>Editing access</button></>}
        {!selected.deletedAt&&selected.permissions.approve&&['pending','expired'].includes(selected.status)&&<button className="primary-btn" onClick={()=>{setDecision('approved');setReason('');setActionError('')}}><Check size={16}/>Approve</button>}
        {canReject(selected)&&<button className="secondary-btn danger-text" onClick={()=>rejectOpportunity(selected)}><X size={15}/>Reject</button>}
        {!selected.deletedAt&&selected.permissions.manage&&selected.status==='rejected'&&<button className="secondary-btn" onClick={()=>{setDecision('pending');setReason('');setActionError('')}}>Request approval</button>}
      </div>
      {!selected.deletedAt&&selected.status==='pending'&&!selected.permissions.approve&&<p className="op-info">An administrator or a team member can approve this opportunity.</p>}
      {!selected.deletedAt&&selected.status==='expired'&&<p className="op-info">The closing deadline has passed. {selected.permissions.approve?'You can approve this opportunity.':selected.permissions.manage?'Assign a team to approve this opportunity.':'An administrator or a team member can approve this opportunity.'}</p>}
      {!selected.deletedAt&&selected.status==='approved'&&!isOpportunityQuoted(selected)&&(opportunityDeadline(selected,regions,deadlineNow).days??0)<0&&<p className="op-info">The deadline has passed. This opportunity stays Approved. Use Project Chase-up for existing submissions.</p>}
      {canQuote(selected)&&<section className="op-quote-prompt" aria-label="Record quote outcome"><div><h3>Ready to record the outcome?</h3><p>Quoted projects appear in Projects and Project Chase-up. Not quoted moves this opportunity to Rejected.</p></div><div className="op-quote-actions"><button className="primary-btn" disabled={busy} onClick={()=>openQuote(selected)}><FileCheck2 size={17}/>Quoted</button><button className="secondary-btn danger-text" disabled={busy} onClick={()=>markNotQuoted(selected)}><XCircle size={17}/>Not quoted</button></div></section>}
      {isOpportunityQuoted(selected)&&<section className="op-quote-summary" aria-label="Recorded quote"><div className="op-quote-summary-heading"><span><FileCheck2 size={20}/><b>Quoted</b></span><strong><Money value={selected.quotedValue??null} precise/></strong></div><p>Electrical services submission value</p><dl><div><dt>Submitted</dt><dd>{selected.submittedDate?opportunityDate(selected.submittedDate):'Not recorded'}</dd></div><div><dt>Recorded by</dt><dd>{selected.quotedByName||'Not recorded'}</dd></div>{selected.quoteNo&&<div><dt>Quote number</dt><dd>{selected.quoteNo}</dd></div>}{selected.submittedByTeamId&&<div><dt>Submitted by team</dt><dd>{teamNames.get(selected.submittedByTeamId)||'Former team'}</dd></div>}</dl>{selected.quoteNote&&<p className="op-preserve-text">{selected.quoteNote}</p>}{selected.submissionIds?.[0]&&<button className="secondary-btn" onClick={()=>onOpenChaseUp(selected.submissionIds![0])}>Open Project Chase-up<ArrowUpRight size={16}/></button>}</section>}
      <div className="op-detail-tabs" role="tablist" aria-label="Opportunity details"><button role="tab" id="op-tab-overview" aria-controls="op-tab-panel" aria-selected={detailTab==='overview'} onClick={()=>setDetailTab('overview')}><ClipboardList size={15}/>Overview</button><button role="tab" id="op-tab-activity" aria-controls="op-tab-panel" aria-selected={detailTab==='activity'} onClick={()=>setDetailTab('activity')}><History size={15}/>Activity <span>{detail?.activityTotal??detail?.activity.length??0}</span></button></div>
      <div role="tabpanel" id="op-tab-panel" aria-labelledby={'op-tab-'+detailTab}>{detailTab==='overview'?<>
        <dl className="op-facts"><div><dt>Project budget / range</dt><dd>{selected.budget||'Not recorded'}</dd></div><div><dt>Estimated tender value</dt><dd><Money value={selected.value}/></dd></div><div><dt>Deadline</dt><dd><DeadlineBadge item={selected} regions={regions} now={deadlineNow}/>{selected.due&&<><small><time dateTime={selected.due}>{opportunityDate(selected.due)}</time></small><small>End of day · {opportunityTimezone(selected.region,regions).replace('Australia/','').replaceAll('_',' ')} time</small></>}</dd></div><div><dt>Category</dt><dd>{selected.category||'Not recorded'}</dd></div><div><dt>Added to register</dt><dd>{selected.addedDate?opportunityDate(selected.addedDate):opportunityDate(selected.createdAt)}</dd></div><div><dt>Location</dt><dd>{selected.location||'Not recorded'}</dd></div><div><dt>Distance</dt><dd>{selected.distanceKm!=null?`${selected.distanceKm} km`:'Not recorded'}<small>From {selected.distanceOrigin||regions.find(r=>r.code===selected.region)?.origin||'origin not recorded'}</small></dd></div><div><dt>Creator</dt><dd>{selected.createdByName||'Imported source'}</dd></div></dl>
        {selected.location&&<a className="op-map-link" target="_blank" rel="noopener noreferrer" href={'https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(selected.distanceOrigin||regions.find(r=>r.code===selected.region)?.origin||'')+'&destination='+encodeURIComponent(selected.location)}><MapPin size={16}/>View route from {selected.region} origin<ArrowUpRight size={14}/></a>}
        {selected.sourceData&&selected.sourceStatus&&<section className="op-detail-section"><h3>Original workbook decision</h3><p>{selected.sourceStatus==='approved'?'Approved':selected.sourceStatus==='rejected'?'Not interested / rejected':'No decision recorded'}{['approved','rejected'].includes(selected.sourceStatus)&&<span className="op-help"> · Decision maker not recorded in the workbook.</span>}</p></section>}<section className="op-detail-section"><h3>Working scope</h3><p className="op-preserve-text">{selected.workingScope||'Working scope has not been recorded yet.'}</p></section>
        <section className="op-detail-section"><h3>Builders</h3><div className="op-tags">{selected.builders.length?selected.builders.map(name=><span key={name}><Building2 size={13}/>{name}</span>):<p className="op-help">Builder to be confirmed.</p>}</div></section>
        <section className="op-detail-section"><h3>Assigned teams and people</h3><div className="op-tags">{assignedNames(selected).length?assignedNames(selected).map((name,i)=><span key={i}><Users size={13}/>{name}</span>):<p className="op-help">No assignment yet.</p>}</div></section>
        {safeOpportunityLink(selected.link)&&<section className="op-detail-section"><h3>Link</h3><OpportunityLink value={selected.link} project={selected.project}/></section>}
        {selected.remarks&&<section className="op-detail-section"><h3>Notes</h3><p className="op-preserve-text">{selected.remarks}</p></section>}
        {selected.decisionByName&&<section className="op-detail-section"><h3>Decision recorded by</h3><p>{selected.decisionByName}{selected.decisionAt?' · '+new Date(selected.decisionAt).toLocaleString('en-AU',{dateStyle:'medium',timeStyle:'short'}):''}</p></section>}{selected.decisionReason&&<section className="op-detail-section"><h3>Decision note</h3><p className="op-preserve-text">{selected.decisionReason}</p></section>}
        {selected.permissions.manage&&<section className="op-detail-section"><h3>Editing access</h3><p className="op-help">The creator and administrators manage this opportunity. {selected.editorTeamIds?.length||selected.editorUserIds?.length?'Additional editors can update project details.':'No additional editors have been added.'}</p><div className="op-tags">{[...(selected.editorTeamIds||[]).map(id=>teamNames.get(id)||'Former team'),...(selected.editorUserIds||[]).map(id=>userNames.get(id)||'Former user')].map((name,i)=><span key={i}>{name}</span>)}</div></section>}
        {selected.sourceData&&Object.keys(selected.sourceData).length>0&&<SourceInfo source={selected.sourceData}/>}
      </>:<div className="op-activity"><p className="op-help">Recorded actions include creation, changes, assignments, access, decisions and deadline events.</p>{detail?.activity.map(event=><article key={event.id}><span className="op-activity-dot"/><div><b>{event.action}</b><small>{event.actorName||'System'} · {new Date(event.createdAt).toLocaleString('en-AU',{dateStyle:'medium',timeStyle:'short'})}</small>{typeof event.details?.reason==='string'&&event.details.reason&&<p>{event.details.reason}</p>}<ActivityDetails details={event.details}/></div></article>)}{!detail?.activity.length&&<p className="op-help">No activity recorded yet.</p>}{activityError&&<p className="error-banner" role="alert">{activityError}</p>}{detail?.hasMoreActivity&&<button className="secondary-btn" disabled={activityLoading} onClick={loadOlderActivity}>{activityLoading?'Loading…':'Load older activity'}</button>}</div>}</div>
      {!selected.deletedAt&&selected.permissions.manage&&<div className="op-danger-zone"><button className="text-btn danger-text" onClick={()=>{setDecision('delete');setReason('');setActionError('')}}><Trash2 size={15}/>Delete opportunity</button></div>}</div>}
    </SheetContent></Sheet>

    <Dialog open={!!form} onOpenChange={open=>{if(!open&&!busy)setForm(null)}}><DialogContent className="op-dialog op-edit-dialog" showCloseButton={!busy}><DialogHeader><DialogTitle>{form?.id?'Edit opportunity':'New opportunity'}</DialogTitle><DialogDescription>{form?.id?'Update project details. Your changes will be recorded in the activity history.':'Add potential work to the register. It will be awaiting approval until an administrator or team member makes a decision.'}</DialogDescription></DialogHeader>{form&&<form onSubmit={saveForm}>
      <div className="op-form-grid"><label className="op-field op-span-two">Project name<input required maxLength={500} value={form.project} onChange={e=>setForm({...form,project:e.target.value})} placeholder="e.g. Community Centre Refurbishment"/></label><label className="op-field">Region<input required list="op-region-options" maxLength={30} value={form.region} onChange={e=>{const value=e.target.value.toUpperCase(),existing=regions.find(r=>r.code===value);setForm({...form,region:value,distanceOrigin:existing?.origin||'',distanceKm:null})}}/><datalist id="op-region-options">{regions.map(r=><option key={r.code} value={r.code}/>)}</datalist></label><label className="op-field">Closing deadline<input type="date" value={form.due} onChange={e=>setForm({...form,due:e.target.value})}/></label><label className="op-field op-span-two">Project location<input maxLength={1000} value={form.location} onChange={e=>setForm({...form,location:e.target.value,distanceKm:null})} placeholder="Street, suburb or site address"/></label>
      <div className="op-field op-span-two"><label htmlFor="op-builder-input">Builders</label><div className="op-builder-input"><input id="op-builder-input" list="op-existing-builders" value={builderDraft} onChange={e=>setBuilderDraft(e.target.value)} placeholder="Choose a builder or type a new name" onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();addBuilder()}}}/><button type="button" className="secondary-btn" onClick={addBuilder} disabled={!builderDraft.trim()}><Plus size={15}/>Add</button></div><datalist id="op-existing-builders">{(result?.builders||[]).map(name=><option key={name} value={name}/>)}</datalist><div className="op-builder-tags">{form.builders.map(name=><span key={name}>{name}<button type="button" aria-label={'Remove '+name} onClick={()=>setForm({...form,builders:form.builders.filter(value=>value!==name)})}><X size={13}/></button></span>)}</div><small>Multiple builders can be linked to one opportunity. New names are saved for future suggestions.</small></div>
      <label className="op-field op-span-two">Working scope<textarea rows={4} maxLength={20000} value={form.workingScope} onChange={e=>setForm({...form,workingScope:e.target.value})} placeholder="Electrical works, exclusions, supply requirements and any scope still to be confirmed…"/></label><label className="op-field">Category<input maxLength={300} value={form.category} onChange={e=>setForm({...form,category:e.target.value})} placeholder="e.g. Commercial, education"/></label><label className="op-field">Budget / value range<input maxLength={300} value={form.budget} onChange={e=>setForm({...form,budget:e.target.value})} placeholder="e.g. $5m–$10m"/></label><label className="op-field">Estimated tender value (AUD)<input type="number" min="0" step="0.01" value={form.value??''} onChange={e=>setForm({...form,value:e.target.value===''?null:Number(e.target.value)})}/></label><label className="op-field">Added date<input type="date" value={form.addedDate} onChange={e=>setForm({...form,addedDate:e.target.value})}/></label>
      <label className="op-field">Distance (km)<input type="number" min="0" step="0.1" value={form.distanceKm??''} onChange={e=>setForm({...form,distanceKm:e.target.value===''?null:Number(e.target.value)})}/></label><label className="op-field">Distance from<input required={!regions.some(r=>r.code===form.region)} maxLength={1000} value={form.distanceOrigin} onChange={e=>setForm({...form,distanceOrigin:e.target.value,distanceKm:null})} placeholder="Office or nominated origin"/></label><p className="op-help op-span-two">Distances are entered or imported. Use the route link in the opportunity to check travel distance.</p><div className="op-field op-span-two"><label htmlFor="op-link-input">Link</label><input id="op-link-input" inputMode="url" autoCapitalize="none" autoCorrect="off" spellCheck={false} maxLength={2048} value={form.link} onChange={e=>setForm({...form,link:e.target.value})} placeholder="https://example.com/project" aria-describedby="op-link-help"/><small id="op-link-help">Optional web address for the project listing, tender portal or shared documents.</small></div><label className="op-field op-span-two">Notes<textarea rows={3} maxLength={20000} value={form.remarks} onChange={e=>setForm({...form,remarks:e.target.value})}/></label></div>
      {actionError&&<div className="error-banner" role="alert">{actionError}</div>}<div className="op-dialog-actions"><button type="button" className="secondary-btn" disabled={busy} onClick={()=>setForm(null)}>Cancel</button><button className="primary-btn" disabled={busy}>{busy?'Saving…':form.id?'Save changes':'Add opportunity'}</button></div></form>}</DialogContent></Dialog>

    <Dialog open={!!quote} onOpenChange={open=>{if(!open&&!busy)setQuote(null)}}><DialogContent className="op-dialog op-edit-dialog op-quote-dialog" showCloseButton={!busy}><DialogHeader><DialogTitle>Record quoted project</DialogTitle><DialogDescription>{quote?.project}. Save the submitted electrical value to open this project in Project Chase-up.</DialogDescription></DialogHeader>{quote&&<form onSubmit={saveQuote}>
      <div className="op-form-grid">
        <div className="op-field op-span-two"><label htmlFor="op-quote-value">Electrical services submission value (AUD)</label><input id="op-quote-value" aria-describedby="op-quote-value-help" autoFocus required type="number" inputMode="decimal" min="0" max="1000000000000000" step="0.01" value={quote.value} onChange={e=>setQuote({...quote,value:e.target.value})} placeholder="Enter the value submitted to the builder"/><small id="op-quote-value-help">The electrical quote amount is separate from the overall project budget.</small></div>
        <label className="op-field">Quote number (optional)<input maxLength={200} value={quote.quoteNo} onChange={e=>setQuote({...quote,quoteNo:e.target.value})} placeholder="e.g. TEC-2026-042"/></label>
        <div className="op-field"><label htmlFor="op-quote-date">Submitted date</label><input id="op-quote-date" aria-describedby="op-quote-date-help" type="date" value={quote.submittedDate} onChange={e=>setQuote({...quote,submittedDate:e.target.value})}/><small id="op-quote-date-help">Leave blank to use today in the opportunity's region.</small></div>
        <div className="op-field op-span-two"><label htmlFor="op-quote-team">Submitted by team</label><select id="op-quote-team" value={quote.submittedByTeamId} onChange={e=>setQuote({...quote,submittedByTeamId:e.target.value})}><option value="">Unassigned</option>{teams.map(team=><option key={team.id} value={team.id}>{team.name}</option>)}</select></div>
        <fieldset className="op-choice-group op-span-two"><legend>Builders quoted to<span>{quote.builders.length} selected</span></legend><div className="op-choice-list">{quote.availableBuilders.map(name=><label key={name}><input type="checkbox" checked={quote.builders.includes(name)} onChange={()=>setQuote({...quote,builders:quote.builders.includes(name)?quote.builders.filter(builder=>builder!==name):[...quote.builders,name]})}/><span><b>{name}</b></span></label>)}</div>{quote.availableBuilders.length?<p className="op-help">Choose at least one builder. The submitted value applies to this project across the selected builders.</p>:<p className="op-help">Add at least one builder to the opportunity before recording a quote. {selected?.permissions.edit&&<button type="button" className="text-btn" onClick={()=>{setQuote(null);edit(selected)}}>Edit opportunity</button>}</p>}</fieldset>
        <div className="op-field op-span-two"><label htmlFor="op-quote-note">Note (optional)</label><textarea id="op-quote-note" rows={4} maxLength={4000} value={quote.note} onChange={e=>setQuote({...quote,note:e.target.value})} placeholder="Submission details, exclusions or follow-up notes…"/></div>
      </div>
      {actionError&&<div className="error-banner" role="alert">{actionError}</div>}<div className="op-dialog-actions"><button type="button" className="secondary-btn" disabled={busy} onClick={()=>setQuote(null)}>Cancel</button><button className="primary-btn" disabled={busy||!quote.builders.length}>{busy?'Saving…':'Save quote'}</button></div>
    </form>}</DialogContent></Dialog>

    <Dialog open={!!management} onOpenChange={open=>{if(!open&&!busy)setManagement(null)}}><DialogContent className="op-dialog op-manage-dialog" showCloseButton={!busy}><DialogHeader><DialogTitle>{management?.kind==='assign'?'Assign teams and people':'Manage editing access'}</DialogTitle><DialogDescription>{management?.kind==='assign'?'Assigning a team automatically approves this opportunity, even after its deadline. Selected people and team members receive a notification.':'Additional editors can change project details. The creator and administrators retain assignment, deletion and access control.'}</DialogDescription></DialogHeader>{management&&<form onSubmit={saveManagement}><div className="op-management-grid"><ChoiceList title="Teams" items={teams} selected={management.teams} onChange={ids=>setManagement({...management,teams:ids})} empty="No teams have been created yet."/><ChoiceList title="People" items={users.map(user=>({...user,hint:teamNames.get(user.teamId||0)||'No team'}))} selected={management.users} onChange={ids=>setManagement({...management,users:ids})} empty="No people available."/></div>{actionError&&<div className="error-banner" role="alert">{actionError}</div>}<div className="op-dialog-actions"><button type="button" className="secondary-btn" disabled={busy} onClick={()=>setManagement(null)}>Cancel</button><button className="primary-btn" disabled={busy}>{busy?'Saving…':management.kind==='assign'?'Save assignments':'Save editing access'}</button></div></form>}</DialogContent></Dialog>

    <Dialog open={!!decision} onOpenChange={open=>{if(!open&&!busy)setDecision(null)}}><DialogContent className="op-dialog op-decision-dialog" showCloseButton={!busy}><DialogHeader><DialogTitle>{decision==='delete'?'Delete opportunity?':decision==='approved'?'Approve opportunity':decision==='rejected'?(rejectingQuote?'Mark as not quoted':'Reject opportunity'):'Request approval again'}</DialogTitle><DialogDescription>{decision==='delete'?`“${selected?.project}” will leave the opportunity register. Its audit history and contributor records will be retained.`:decision==='pending'?'Return this opportunity to Awaiting approval. Its deadline must be current or blank.':decision==='approved'?`${selected?.project}. This opportunity will stay Approved after its deadline.`:rejectingQuote?`${selected?.project} will move to Rejected. Your decision, name and time will be recorded.`:`${selected?.project}. Your decision, name and time will be recorded.`}</DialogDescription></DialogHeader><form onSubmit={saveDecision}>{decision!=='delete'&&<label className="op-field">{decision==='rejected'?'Reason for rejection (optional)':'Decision note (optional)'}<textarea maxLength={4000} rows={4} value={reason} onChange={e=>setReason(e.target.value)} placeholder={decision==='rejected'?'Add a reason if helpful, or leave this blank…':'Add context for the team, or leave this blank…'}/></label>}{actionError&&<div className="error-banner" role="alert">{actionError}</div>}<div className="op-dialog-actions"><button type="button" className="secondary-btn" disabled={busy} onClick={()=>setDecision(null)}>Cancel</button><button className={decision==='delete'||decision==='rejected'?'op-danger-button':'primary-btn'} disabled={busy}>{busy?'Saving…':decision==='delete'?'Delete opportunity':decision==='approved'?'Approve':decision==='rejected'?(rejectingQuote?'Move to Rejected':'Reject opportunity'):'Request approval'}</button></div></form></DialogContent></Dialog>
  </section>;
}
